# Arithmetic loop plus recursive Fibonacci calls.
def fib(n):
    if n < 2:
        return n
    return fib(n - 1) + fib(n - 2)

def run():
    total = 0
    for i in range(700000):
        total += (i * i) % 97

    fib_sum = 0
    for i in range(20):
        fib_sum += fib(i)

    print("sum=%d fibSum=%d" % (total, fib_sum))

run()

# Stress seed: same arithmetic/recursion workload at much higher volume,
