def fib(n):
    if n < 2:
        return n
    return fib(n - 1) + fib(n - 2)

def run():
    total = 0
    for i in range(30000000):
        total += (i * i) % 97

    fib_sum = 0
    for i in range(120):
        fib_sum += fib(i % 20)

    print("sum=%d fibSum=%d" % (total, fib_sum))

run()
